import{_ as o,o as r,c as d,a0 as e}from"./chunks/framework.UHt1LHnn.js";const u=JSON.parse('{"title":"CHAPTER 0. 기획자에게 Claude Code가 필요한 이유","description":"","frontmatter":{},"headers":[],"relativePath":"ch0.md","filePath":"ch0.md"}'),a={name:"ch0.md"};function n(s,t,l,i,g,h){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="chapter-0-기획자에게-claude-code가-필요한-이유" tabindex="-1">CHAPTER 0. 기획자에게 Claude Code가 필요한 이유 <a class="header-anchor" href="#chapter-0-기획자에게-claude-code가-필요한-이유" aria-label="Permalink to &quot;CHAPTER 0. 기획자에게 Claude Code가 필요한 이유&quot;">​</a></h1><blockquote><p>Claude Code란 무엇인지, 왜 기획자에게 유용한지를 설명합니다.</p></blockquote><h2 id="💬-기획자의-하루-어디서-시간이-사라지는가" tabindex="-1">💬 기획자의 하루, 어디서 시간이 사라지는가 <a class="header-anchor" href="#💬-기획자의-하루-어디서-시간이-사라지는가" aria-label="Permalink to &quot;💬 기획자의 하루, 어디서 시간이 사라지는가&quot;">​</a></h2><p>기획자의 하루는 생각보다 많은 반복으로 채워져 있습니다.</p><ul><li>회의가 끝나면 회의록을 정리하고 Confluence에 올린다</li><li>기능 정의가 바뀌면 스펙 문서를 찾아서 수정하고, 관련 Jira 티켓도 업데이트한다</li><li>API 기획을 완료하면 개발팀에 전달하기 전에 직접 Postman으로 검증해본다</li><li>경쟁사 분석이 필요하면 탭을 수십 개 열어 자료를 수동으로 취합한다</li></ul><p>이 모든 과정은 **&quot;기획&quot;이 아닌 &quot;작업&quot;**입니다. 실제 고민과 판단에 써야 할 시간이, 반복적인 실행에 소모되고 있습니다.</p><p>Claude Code는 이 <strong>&quot;작업&quot;의 상당 부분을 자동화</strong>하고, 기획자가 본질적인 사고에 집중할 수 있도록 돕습니다.</p><h2 id="🤖-claude-code란-무엇인가" tabindex="-1">🤖 Claude Code란 무엇인가 <a class="header-anchor" href="#🤖-claude-code란-무엇인가" aria-label="Permalink to &quot;🤖 Claude Code란 무엇인가&quot;">​</a></h2><p>Claude Code는 Anthropic이 만든 <strong>터미널 기반 AI 코딩 에이전트</strong>입니다. 단순히 질문에 답하는 챗봇이 아니라, 실제 파일을 읽고 수정하며, 외부 시스템과 연동하고, 명령을 실행하는 <strong>능동적인 작업 도구</strong>입니다.</p><table tabindex="0"><thead><tr><th>구분</th><th>설명</th></tr></thead><tbody><tr><td><strong>실행 환경</strong></td><td>터미널(CLI) 기반으로 동작, 프로젝트 디렉토리 전체를 컨텍스트로 인식</td></tr><tr><td><strong>MCP 연동</strong></td><td>Model Context Protocol을 통해 Confluence, Jira, Figma, GitHub 등 외부 도구와 직접 연결</td></tr><tr><td><strong>파일 처리</strong></td><td>문서 생성·수정, 코드 분석, JSON 파싱 등 실제 결과물을 직접 만들어냄</td></tr><tr><td><strong>커스터마이징</strong></td><td>CLAUDE.md 설정 파일과 Slash Commands로 팀 맞춤 워크플로우 구성 가능</td></tr></tbody></table><h2 id="🙋-기획자에게-특히-유용한-이유" tabindex="-1">🙋 기획자에게 특히 유용한 이유 <a class="header-anchor" href="#🙋-기획자에게-특히-유용한-이유" aria-label="Permalink to &quot;🙋 기획자에게 특히 유용한 이유&quot;">​</a></h2><p>Claude Code는 개발자만을 위한 도구가 아닙니다. 오히려 <strong>개발과 기획의 경계에 있는 테크 기획자</strong>에게 가장 강력한 도구가 됩니다.</p><div class="tip custom-block"><p class="custom-block-title">✅ 기획자가 Claude Code로 할 수 있는 것</p><ul><li>📄 <strong>문서 자동화</strong> — 회의록·기획서·스펙 문서를 Confluence에 자동 생성·수정</li><li>🎫 <strong>티켓 관리</strong> — Jira 티켓 생성, 조회, 상태 변경을 명령어 한 줄로 처리</li><li>🎨 <strong>시안 제작</strong> — Figma 컴포넌트를 참조해 기획 화면 초안을 직접 제작</li><li>🔧 <strong>API 검증</strong> — Swagger JSON으로 자동화 테스트 툴을 직접 구축하여 기획 검증</li><li>📊 <strong>리서치 자동화</strong> — 경쟁사·레퍼런스 분석 보고서를 빠르게 초안 생성</li><li>📝 <strong>가이드 문서 작성</strong> — GitHub에서 공식 문서를 clone해 초안을 빠르게 완성</li></ul></div><h2 id="⚡-일반-ai-챗봇과-무엇이-다른가" tabindex="-1">⚡ 일반 AI 챗봇과 무엇이 다른가 <a class="header-anchor" href="#⚡-일반-ai-챗봇과-무엇이-다른가" aria-label="Permalink to &quot;⚡ 일반 AI 챗봇과 무엇이 다른가&quot;">​</a></h2><table tabindex="0"><thead><tr><th>비교 항목</th><th>일반 AI 챗봇</th><th>Claude Code</th></tr></thead><tbody><tr><td><strong>결과물 생성</strong></td><td>텍스트 답변만 제공</td><td><strong>실제 파일·문서 직접 생성</strong></td></tr><tr><td><strong>외부 시스템 연동</strong></td><td>❌ 불가</td><td><strong>✅ MCP로 직접 연동</strong></td></tr><tr><td><strong>프로젝트 컨텍스트</strong></td><td>대화 내용만 기억</td><td><strong>디렉토리 전체 파악</strong></td></tr><tr><td><strong>반복 작업 자동화</strong></td><td>매번 수동 입력 필요</td><td><strong>커스텀 명령어로 자동화</strong></td></tr><tr><td><strong>API 검증</strong></td><td>설명만 가능</td><td><strong>툴 직접 구축 및 실행</strong></td></tr></tbody></table><h2 id="🗺️-이-가이드를-활용하는-방법" tabindex="-1">🗺️ 이 가이드를 활용하는 방법 <a class="header-anchor" href="#🗺️-이-가이드를-활용하는-방법" aria-label="Permalink to &quot;🗺️ 이 가이드를 활용하는 방법&quot;">​</a></h2><p>이 백서는 <strong>처음부터 순서대로 읽을 필요가 없습니다.</strong> 각 챕터는 독립적으로 구성되어 있으므로, 지금 당장 필요한 업무부터 바로 참고하실 수 있습니다.</p><table tabindex="0"><thead><tr><th>지금 이런 상황이라면</th><th>이 챕터로 바로 이동</th></tr></thead><tbody><tr><td>Claude Code가 처음이다</td><td><strong>CH.1</strong> — 환경 구축</td></tr><tr><td>Confluence 문서 작업이 너무 많다</td><td><strong>CH.3</strong> — MCP Confluence 연동</td></tr><tr><td>Jira 티켓 관리가 번거롭다</td><td><strong>CH.4</strong> — MCP Jira 연동</td></tr><tr><td>기획 시안을 빠르게 잡고 싶다</td><td><strong>CH.5</strong> — MCP Figma 연동</td></tr><tr><td>API 검증을 자동화하고 싶다</td><td><strong>CH.7</strong> — API 자동화 테스트 툴</td></tr><tr><td>리서치 보고서 작성이 오래 걸린다</td><td><strong>CH.8</strong> — 경쟁사·레퍼런스 분석 자동화</td></tr></tbody></table><blockquote><p>💡 Claude Code는 설치 후 바로 모든 기능을 쓸 수 있는 것이 아닙니다. MCP 연동, CLAUDE.md 설정 등 초기 세팅이 필요합니다. <strong>CH.1 환경 구축</strong>부터 시작하면 이후 챕터가 훨씬 수월합니다.</p></blockquote>',19)])])}const C=o(a,[["render",n]]);export{u as __pageData,C as default};
